(window.LADDER_CARDS=window.LADDER_CARDS||{})["42a"]=[{"q": "Adding the counts of links at every dot of a graph gives what?", "a": "twice the number of links", "w": ["the number of links", "the number of dots", "the number of pairs of dots"], "why": "The ends-count technique: each link has two ends."}, {"q": "Can a graph have link counts 3, 3, 2, 1?", "a": "no", "w": ["yes", "only with a loop", "only if it has a cycle"], "why": "The total 9 is odd, but it must be twice the links."}, {"q": "A walk joins u to w. What else must join them?", "a": "a path", "w": ["a cycle", "a tree", "a link"], "why": "The walk-to-path technique: cut out loops from a least walk."}, {"q": "Which condition makes a graph two-sided?", "a": "no cycle of odd length", "w": ["no triangle", "every count even", "in one piece"], "why": "The odd-cycle technique."}, {"q": "The five-ring has no triangle. Is it two-sided?", "a": "no", "w": ["yes", "only if drawn flat", "it depends on the names"], "why": "It is itself a cycle of odd length."}, {"q": "How many graphs are there on 4 named dots?", "a": "64", "w": ["11", "16", "24"], "why": "6 possible links, each in or out: 2⁶."}, {"q": "How many shapes of graph are there on 4 dots?", "a": "11", "w": ["64", "6", "24"], "why": "Counted in 42·cb19 by averaging what each shuffle keeps."}, {"q": "K₃,₃ and the prism both have six dots with three links each. What tells them apart?", "a": "the prism has triangles, K₃,₃ has none", "w": ["the number of links", "the counts at the dots", "nothing; they are the same shape"], "why": "A matching that carries links carries triangles to triangles."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["42b"]=[{"q": "A tree has 12 dots. How many links?", "a": "11", "w": ["12", "13", "24"], "why": "The links-of-a-tree technique: n − 1."}, {"q": "A graph with n dots is in one piece and has n − 1 links. What else follows?", "a": "it has no cycle", "w": ["it is two-sided only", "it has a round of the dots", "nothing more"], "why": "The any-two-of-three technique."}, {"q": "How many trees are there on 5 named dots?", "a": "125", "w": ["25", "60", "3"], "why": "nⁿ⁻² by the leaf-code technique."}, {"q": "A dot has 4 links in a tree. How often does it appear in the leaf code?", "a": "3 times", "w": ["4 times", "once", "never"], "why": "Each dot appears one time fewer than its count of links."}, {"q": "Which dots never appear in a tree’s leaf code?", "a": "its ends", "w": ["the dot with most links", "dots 1 and n", "none; every dot appears"], "why": "An end appears d − 1 = 0 times."}, {"q": "A triangle and a lone dot have 4 dots and 3 links. Are they a tree?", "a": "no, not in one piece", "w": ["yes", "yes, a tree with a cycle", "only if named"], "why": "n − 1 links alone does not make a tree."}, {"q": "Dropping a link that lies on a cycle does what to a graph in one piece?", "a": "keeps it in one piece", "w": ["splits it in two", "makes it a tree", "removes a dot"], "why": "Any walk through the link can go round the rest of the cycle."}, {"q": "Does nⁿ⁻² count shapes of tree?", "a": "no, named trees", "w": ["yes", "only for n prime", "only for stars"], "why": "Many named trees share one shape."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["42c"]=[{"q": "A graph in one piece has a closed tour of every link exactly when?", "a": "every dot has an even count", "w": ["every dot has count 2", "it has no cycle", "it is two-sided"], "why": "The even-tour technique."}, {"q": "Exactly two dots have odd counts. What exists?", "a": "a tour of the links from one to the other", "w": ["a closed tour", "a round of the dots", "nothing"], "why": "The open-tour technique."}, {"q": "The seven bridges: why no tour?", "a": "four parts have odd counts", "w": ["the river is too wide", "two bridges join the same parts", "the town is not in one piece"], "why": "At most two dots can be the start and the end."}, {"q": "A cycle through every dot exactly once is called what here?", "a": "a round of the dots", "w": ["a tour of the links", "a tree", "a matching"], "why": "Dots, not links."}, {"q": "Every dot of a graph with n ≥ 3 dots is linked to at least n/2. What follows?", "a": "it has a round of the dots", "w": ["it has a closed tour of the links", "it is a tree", "nothing"], "why": "The half-the-dots technique."}, {"q": "Is there a quick count at the dots that settles whether a round of the dots exists?", "a": "none is known", "w": ["yes, all counts even", "yes, counts at least 2", "yes, n − 1 links"], "why": "It is among 41h’s hard questions."}, {"q": "Two separate triangles: every count is even. Is there a closed tour of the links?", "a": "no", "w": ["yes", "yes, through a shared dot", "only an open one"], "why": "The technique needs the graph in one piece."}, {"q": "Taking 2 dots from K₂,₃ leaves 3 pieces. What does that show?", "a": "K₂,₃ has no round of the dots", "w": ["K₂,₃ is not flat", "K₂,₃ has a closed tour", "K₂,₃ is a tree"], "why": "A cycle cut at k dots falls into at most k pieces."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["42d"]=[{"q": "A flat drawing in one piece: V − E + F = ?", "a": "2", "w": ["0", "1", "V"], "why": "The flat-count technique, from 34f."}, {"q": "A flat graph with V ≥ 3 dots has at most how many links?", "a": "3V − 6", "w": ["2V − 4", "V − 1", "V²/4"], "why": "The flat-ceiling technique; with no triangle, 2V − 4."}, {"q": "Which bound shows K₃,₃ is not flat?", "a": "E ≤ 2V − 4, since it has no triangle", "w": ["E ≤ 3V − 6", "E ≤ V − 1", "V − E + F = 0"], "why": "9 > 8, though 9 ≤ 12."}, {"q": "K₅ has 10 links and 5 dots. Why is it not flat?", "a": "10 > 3 · 5 − 6 = 9", "w": ["it has a triangle", "it is two-sided", "every count is even"], "why": "The flat-ceiling technique."}, {"q": "Every flat graph has a dot with at most how many links?", "a": "five", "w": ["four", "six", "three"], "why": "The five-or-fewer technique."}, {"q": "How many colours suffice for every flat graph, by the five-colour technique?", "a": "five", "w": ["four", "six", "three"], "why": "Four is true too, but proved by computer (42·now)."}, {"q": "Why is 3F = E wrong for a flat graph?", "a": "each link borders two faces: 3F ≤ 2E", "w": ["faces may have two links", "F counts the outside face twice", "it is right"], "why": "Each rim has at least 3 links, each link two faces."}, {"q": "What is held in trust on 42d?", "a": "that a closed curve splits the sheet in two", "w": ["that five colours suffice", "that V − E + F = 2", "that K₅ is not flat"], "why": "Used in the swap of the five-colour technique."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["42e"]=[{"q": "On a two-sided graph, some matching covers X exactly when?", "a": "every part S of X has at least |S| neighbours", "w": ["every dot has a neighbour", "|X| = |Y|", "every dot has the same count"], "why": "The marriage technique."}, {"q": "A matching has no growing path. What follows?", "a": "it is as large as any matching", "w": ["it covers every dot", "it is the only largest one", "it can be added to"], "why": "The growing-path technique."}, {"q": "On a two-sided graph, the most links in a matching equals?", "a": "the fewest dots in a cover", "w": ["the number of dots on the smaller side", "the fewest links in a cover", "half the links"], "why": "The cover-equals-matching technique."}, {"q": "The triangle: largest matching and smallest cover?", "a": "1 and 2", "w": ["1 and 1", "2 and 2", "3 and 3"], "why": "Covers equal matchings only on two-sided graphs."}, {"q": "A matching that cannot be added to is at least what share of a largest one?", "a": "half", "w": ["all of it", "a third", "nothing is promised"], "why": "Each link of the largest touches the smaller one."}, {"q": "Two dots of X both linked only to one y. Which check fails?", "a": "|N(S)| ≥ |S| for S of both", "w": ["each single dot has a neighbour", "every count is even", "the graph is two-sided"], "why": "Checking single dots is not enough."}, {"q": "Every dot of a two-sided graph has exactly k ≥ 1 links. What follows?", "a": "a matching covers both sides", "w": ["no matching covers X", "the graph is a tree", "k must be even"], "why": "k|S| links land on at least |S| neighbours."}, {"q": "When X is endless, does the marriage technique hold?", "a": "no; the condition can hold with no matching", "w": ["yes, always", "yes, if Y is endless too", "only for k-link graphs"], "why": "Its proof is induction on finite |X|."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["42f"]=[{"q": "The value of any flow is at most what?", "a": "the capacity of any cut", "w": ["the largest capacity", "the number of links", "the smallest capacity"], "why": "The flow-under-cut technique."}, {"q": "When no route from s to t has room, what do the dots reachable from s form?", "a": "a cut whose capacity is the flow’s value", "w": ["a cycle", "a matching", "a tree"], "why": "The bottleneck technique: largest flow = smallest cut."}, {"q": "Room back on a link carrying flow f is?", "a": "f", "w": ["c − f", "c", "0"], "why": "Sending less along it is sending some back."}, {"q": "Why may a route with room step back against a link?", "a": "to undo part of an earlier poor choice", "w": ["to save capacity", "it may not", "to reach a dot twice"], "why": "Without it the push can stop below the largest flow."}, {"q": "Every capacity is a whole number. What does the whole-flow technique give?", "a": "a largest flow with whole values", "w": ["a unique largest flow", "a flow of value 1", "a cut of capacity 0"], "why": "Each push adds a whole number; pushing stops."}, {"q": "A two-sided graph becomes a network with s → X → Y → t, capacity 1. Its largest flow is?", "a": "the largest matching", "w": ["the smallest cut of links", "|X|", "the number of links"], "why": "Whole flows of 0s and 1s are matchings."}, {"q": "A cut’s capacity counts which links?", "a": "those from S to the rest", "w": ["every link crossing either way", "links inside S", "links into S"], "why": "Flow back into S only lowers the net."}, {"q": "With capacities that are not fractions, pushing can do what?", "a": "go on for ever, settling below the largest flow", "w": ["always stop", "exceed the smallest cut", "give a negative flow"], "why": "The falling-measure technique needs whole steps."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["42g"]=[{"q": "If the allowed plans have a corner and the value is bounded above, where is a best plan?", "a": "at some corner", "w": ["in the middle", "at (0, 0)", "nowhere"], "why": "The tight-corner technique."}, {"q": "For an allowed plan x and covering prices y, which holds?", "a": "c · x ≤ b · y", "w": ["c · x ≥ b · y", "c · x = b · y always", "b · y ≤ 0"], "why": "The price-bound technique."}, {"q": "Ax ≤ b has no answer exactly when?", "a": "some y ≥ 0 has yᵀA = 0 and y · b < 0", "w": ["A has no inverse", "b < 0", "some x has Ax > b"], "why": "The no-answer technique; the certificate is checked by multiplying."}, {"q": "A program has an allowed plan and its twin covering prices. What follows?", "a": "the best plan earns the least price total", "w": ["the twin has no answer", "the best plan is unique", "the plan earns more than the prices"], "why": "The equal-prices technique."}, {"q": "The glass works: max 3x + 5y with x ≤ 4, 2y ≤ 12, 3x + 2y ≤ 18. Best corner?", "a": "(2, 6), earning 36", "w": ["(4, 3), earning 27", "(0, 6), earning 30", "(4, 6), earning 42"], "why": "Prices (0, 3/2, 1) total 36 too."}, {"q": "What does the one-out technique do?", "a": "removes one unknown from a list of limits", "w": ["finds the best corner", "adds a slack", "solves the twin"], "why": "Pair each upper bound on xₙ with each lower bound."}, {"q": "A limit is slack at the best plan. Its price is?", "a": "0", "w": ["the largest price", "1", "negative"], "why": "Equality at the best plan forces it (42g.6.3)."}, {"q": "Can a program and its twin both have no answers?", "a": "yes", "w": ["no", "only if b = 0", "only with one unknown"], "why": "x − y ≤ 1, −x + y ≤ −2 is an example."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["42h"]=[{"q": "In a game of gain against loss, max over x of min over y equals?", "a": "min over y of max over x", "w": ["0", "the largest entry", "the average entry"], "why": "The minimax technique: the value of the game."}, {"q": "Which is always true, before the minimax technique?", "a": "max min ≤ min max", "w": ["max min ≥ min max", "max min = 0", "min max = 0"], "why": "The guarantee-order technique."}, {"q": "Against a fixed mix x, the column player’s best answer can be?", "a": "a single column", "w": ["a mix of all columns", "the same mix x", "nothing"], "why": "The payment is an average of the columns’ payments."}, {"q": "In a two-by-two game with no safe choice, each player’s best mix makes what equal?", "a": "the other player’s two choices’ payments", "w": ["their own two chances", "the entries of the grid", "nothing"], "why": "The indifference technique."}, {"q": "The penalty game: how often does the taker kick left?", "a": "about 38%", "w": ["50%", "about 62%", "always"], "why": "0.58x + 0.93(1 − x) = 0.95x + 0.70(1 − x)."}, {"q": "Both confess in the prisoners’ game. What is it?", "a": "an equilibrium, worse for both than both silent", "w": ["the best for both", "not an equilibrium", "a safe choice for neither"], "why": "Neither gains by changing alone."}, {"q": "The minimax technique comes from which earlier technique?", "a": "the equal-prices technique", "w": ["the marriage technique", "the bottleneck technique", "the crowded-box technique"], "why": "The two players’ programs are twins."}, {"q": "A game has an entry least in its row and largest in its column. What follows?", "a": "both players have safe choices", "w": ["no value exists", "both must mix", "the value is 0"], "why": "A pair of safe choices."}];
(window.LADDER_CARDS=window.LADDER_CARDS||{})["42i"]=[{"q": "More than n · k things in n boxes. What follows?", "a": "some box has more than k", "w": ["every box has k", "some box is empty", "some box has exactly k"], "why": "The crowded-box technique."}, {"q": "A row of 10 different numbers. What must it hold?", "a": "a rise or a fall of 4", "w": ["a rise of 4", "a fall of 4", "a rise and a fall of 4"], "why": "The rise-or-fall technique: n² + 1 = 10, n = 3."}, {"q": "How many of 1 to 100 are divisible by none of 2, 3, 5?", "a": "26", "w": ["0", "3", "33"], "why": "100 − 103 + 32 − 3, by the over-and-under technique."}, {"q": "D₅, the arrangements of 5 moving everything, is?", "a": "44", "w": ["120", "24", "53"], "why": "The nearest whole number to 120/e."}, {"q": "The share of arrangements moving everything heads to?", "a": "1/e", "w": ["1/2", "0", "1"], "why": "The wrong-coats technique."}, {"q": "A member lying in exactly 3 of the sets is counted how many times by the over-and-under sum?", "a": "0", "w": ["1", "3", "−1"], "why": "1 − 3 + 3 − 1 = (1 − 1)³."}, {"q": "Functions from a 4-set onto a 3-set number?", "a": "36", "w": ["81", "48", "24"], "why": "81 − 3 · 16 + 3 · 1."}, {"q": "737 015 people, 150 001 hair counts. What follows?", "a": "at least five share a count", "w": ["exactly five share a count", "everyone has a different count", "at most four share"], "why": "737 015 > 4 · 150 001."}];
